def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    fg = next(x for x in Counter(v for row in grid for v in row) if x != bg)
    out = [row[:] for row in grid]

    for top in range(h):
        for bottom in range(top + 2, h):
            for left in range(w):
                for right in range(left + 2, w):
                    if (all(grid[top][c] == fg and grid[bottom][c] == fg
                            for c in range(left, right + 1))
                        and all(grid[r][left] == fg and grid[r][right] == fg
                                for r in range(top, bottom + 1))):
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                out[r][c] = 4

    return out
